[ -f "$target_copy/backend/go.mod" ] || { echo 'target must be a source copy' >&2; exit 2; }
case "$target_copy" in /|/Users/lin/.codex/worktrees/08de/sub2api-no2api) echo 'refusing original workspace' >&2; exit 2;; esac
